strip_yaml_frontmatter <- function(lines) {
  content_start <- 1
  if (length(lines) > 0 && lines[1] == "---") {
    yaml_end <- which(lines == "---")
    if (length(yaml_end) >= 2) {
      content_start <- yaml_end[2] + 1
    }
  }
  return(lines[content_start:length(lines)])
}

# Test cases
test_lines_with_yaml <- c("---", "title: test", "---", "content")
test_lines_no_yaml <- c("content")
test_lines_broken_yaml <- c("---", "title: test", "content")

print(strip_yaml_frontmatter(test_lines_with_yaml))
print(strip_yaml_frontmatter(test_lines_no_yaml))
print(strip_yaml_frontmatter(test_lines_broken_yaml))

