  # User skills from config directory (configurable via option)
  user_skills_dir <- getOption("side.skills_dir", default_user_skills_dir())
  if (dir.exists(user_skills_dir)) {
    dirs <- c(dirs, user_skills_dir)
  }

  dirs
}

