strip_yaml_frontmatter <- function(lines) {
  if (length(lines) == 0) {
    return(lines)
  }
  content_start <- 1
  if (lines[1] == "---") {
    yaml_end <- which(lines == "---")
    if (length(yaml_end) >= 2) {
      content_start <- yaml_end[2] + 1
    }
  }
  lines[content_start:length(lines)]
}

