# Test cases
test_cases <- list(
  list(name = "No YAML", lines = c("line 1", "line 2"), expected = 1),
  list(name = "Empty", lines = character(0), expected = 1),
  list(name = "Single separator", lines = c("---", "line 1"), expected = 1),
  list(name = "Valid YAML", lines = c("---", "key: val", "---", "line 1"), expected = 4),
  list(name = "Multiple separators", lines = c("---", "a", "---", "b", "---", "c"), expected = 4)
)

results <- vapply(test_cases, function(tc) {
  res <- strip_yaml_frontmatter(tc$lines)
  if (res == tc$expected) {
    return(TRUE)
  } else {
    cat(sprintf("Failed %s: expected %d, got %d\n", tc$name, tc$expected, res))
    return(FALSE)
  }
}, logical(1))

print(all(results))

