# Load the file to get the functions in the environment
# Since we can't 'source' a file and expect it to work if it has dependencies not in the path, 
# we will re-define the helper and the function logic for verification.

strip_yaml_frontmatter <- function(lines) {
  content_start <- 1
  if (length(lines) > 0 && lines[1] == "---") {
    yaml_end <- which(lines == "---")
    if (length(yaml_end) >= 2) {
      content_start <- yaml_end[2] + 1
    }
  }
  return(content_start)
}

# Mocking the part of fetch_skill_impl that uses it
get_content_after_yaml <- function(skill_content) {
  content_start <- strip_yaml_frontmatter(skill_content)
  skill_text <- paste(
    skill_content[content_start:length(skill_content)],
    collapse = "\n"
  )
  return(skill_text)
}

# Test cases
test_cases <- list(
  list(name = "No YAML", lines = c("line 1", "line 2"), expected = "line 1\nline 2"),
  list(name = "Empty", lines = character(0), expected = ""),
  list(name = "Valid YAML", lines = c("---", "key: val", "---", "line 1", "line 2"), expected = "line 1\nline 2"),
  list(name = "Malformed YAML (no end)", lines = c("---", "key: val", "line 1"), expected = "---\nkey: val\nline 1")
)

results <- vapply(test_cases, function(tc) {
  # Handle empty case specifically for paste behavior
  if (length(tc$lines) == 0) {
     res <- ""
  } else {
     res <- get_content_after_yaml(tc$lines)
  }

  if (res == tc$expected) {
    return(TRUE)
  } else {
    cat(sprintf("Failed %s: expected [%s], got [%s]\n", tc$name, tc$expected, res))
    return(FALSE)
  }
}, logical(1))

print(all(results))

