extract_skill_metadata <- function(skill_path) {
  lines <- readLines(skill_path, warn = FALSE)

  content_start <- remove_yaml_frontmatter(lines)

  if (content_start == 1) {
    return(list())
  }

  # The YAML part is between the first "---" and the second "---"
  # Our helper returns the index of the line AFTER the second "---"
  # So the YAML lines are from 2 to content_start - 2
  yaml_lines <- lines[2:(content_start - 2)]
  yaml_text <- paste(yaml_lines, collapse = "\n")

  tryCatch(
    yaml::yaml.load(yaml_text),
    error = function(e) list()
  )
}

