test_lines <- list(
  c("---", "key: value", "---", "actual content"),
  c("no frontmatter here"),
  c("---", "single line"),
  c("---", "key: value"),
  character(0)
)

results <- lapply(test_lines, function(l) {
  # Using the function from the environment if it was sourced, 
  # but since I'm in a fresh clone by default unless persist=TRUE, 
  # and I didn't persist to a file, I should define it here for testing 
  # or assume it's available if I were in a real session.
  # For this tool call, I'll redefine it to ensure it runs.
  strip_yaml_frontmatter <- function(lines) {
    content_start <- 1
    if (length(lines) > 0 && lines[1] == "---") {
      yaml_end <- which(lines == "---")
      if (length(yaml_end) >= 2) {
        content_start <- yaml_end[2] + 1
      }
    }
    content_start
  }
  strip_yaml_frontmatter(l)
})

print(results)

